/*
 * builtin-diff.rs
 *
 * Builtin diff command: Analyze two perf.data input files, look up and read
 * DSOs and symbol information, sort them and produce a diff.
 *
 * Rust source-level translation of perf/builtin-diff.c.  External perf/linux
 * declarations are intentionally left as foreign items or opaque C types.
 */

