static mut compute_wdiff_w2: s64 = 0;
static mut cpu_list: *const c_char = ptr::null();
static mut cpu_bitmap: [c_ulong; MAX_NR_CPUS / (8 * mem::size_of::<c_ulong>())] = [0; MAX_NR_CPUS / (8 * mem::size_of::<c_ulong>())];
static compute_names: [*const c_char; COMPUTE_MAX] = [b"delta\0".as_ptr() as _, b"ratio\0".as_ptr() as _, b"wdiff\0".as_ptr() as _, b"delta-abs\0".as_ptr() as _, b"cycles\0".as_ptr() as _];
static mut compute: c_int = COMPUTE_DELTA_ABS;
static compute_2_hpp: [c_int; COMPUTE_MAX] = [PERF_HPP_DIFF__DELTA as c_int, PERF_HPP_DIFF__RATIO as c_int, PERF_HPP_DIFF__WEIGHTED_DIFF as c_int, PERF_HPP_DIFF__DELTA_ABS as c_int, PERF_HPP_DIFF__CYCLES as c_int];
static columns: [header_column; PERF_HPP_DIFF__MAX_INDEX] = [
    header_column{name:b"Baseline\0".as_ptr() as _,width:0}, header_column{name:b"Period\0".as_ptr() as _,width:14}, header_column{name:b"Base period\0".as_ptr() as _,width:14}, header_column{name:b"Delta\0".as_ptr() as _,width:7}, header_column{name:b"Ratio\0".as_ptr() as _,width:14}, header_column{name:b"Weighted diff\0".as_ptr() as _,width:14}, header_column{name:b"Formula\0".as_ptr() as _,width:MAX_COL_WIDTH as c_int}, header_column{name:b"Delta Abs\0".as_ptr() as _,width:7}, header_column{name:b"[Program Block Range] Cycles Diff\0".as_ptr() as _,width:70}, header_column{name:b"stddev/Hist\0".as_ptr() as _,width:(NUM_SPARKS+9) as c_int},
];
static mut pdiff: perf_diff = unsafe { mem::zeroed() };

unsafe fn test_bit(bit:u32, map:*mut c_ulong)->bool { ((*map.add(bit as usize/(8*mem::size_of::<c_ulong>()))) & (1usize << (bit as usize%(8*mem::size_of::<c_ulong>()))) as c_ulong) != 0 }
unsafe fn zfree<T>(p:*mut *mut T){ if !(*p).is_null(){ free(*p as *mut c_void); *p=ptr::null_mut(); } }
unsafe fn is_err<T>(p:*mut T)->bool { (p as isize) < 0 && (p as isize) > -4096 }
unsafe fn ptr_err<T>(p:*mut T)->c_int { p as isize as c_int }
unsafe fn he_from_rb(n:*mut rb_node)->*mut hist_entry { n as *mut hist_entry }
unsafe fn bh_from_he(he:*mut hist_entry)->*mut block_hist { he as *mut block_hist }
unsafe fn dfmt_from_fmt(fmt:*mut perf_hpp_fmt)->*mut diff_hpp_fmt { fmt as *mut diff_hpp_fmt }

unsafe extern "C" fn setup_compute_opt_wdiff(opt:*const c_char)->c_int{ let mut ret=-EINVAL; if opt.is_null(){goto_out(ret)} else { let mut w2=strchr(opt,',' as c_int); if w2.is_null(){goto_out(ret)} else { w2=w2.add(1); if *w2==0 {goto_out(ret)} else { compute_wdiff_w1=strtol(opt,ptr::null_mut(),10) as s64; compute_wdiff_w2=strtol(w2,ptr::null_mut(),10) as s64; if compute_wdiff_w1!=0 && compute_wdiff_w2!=0 { pr_debug(b"compute wdiff w1(%ld) w2(%ld)\n\0".as_ptr() as _,compute_wdiff_w1,compute_wdiff_w2); ret=0; } goto_out(ret) }}}}
unsafe fn goto_out(ret:c_int)->c_int{ if ret!=0{ pr_err(b"Failed: wrong weight data, use 'wdiff:w1,w2'\n\0".as_ptr() as _);} ret }
unsafe fn setup_compute_opt(opt:*const c_char)->c_int{ if compute==COMPUTE_WEIGHTED_DIFF{return setup_compute_opt_wdiff(opt)} if !opt.is_null(){pr_err(b"Failed: extra option specified '%s'\0".as_ptr() as _,opt); return -EINVAL} 0 }

unsafe extern "C" fn setup_compute(opt:*const option,str_:*const c_char,unset:c_int)->c_int{ let cp=(*opt).value as *mut c_int; let mut cstr=str_; let mut buf=[0 as c_char;50]; let mut option=strchr(str_,':' as c_int); if str_.is_null(){*cp=COMPUTE_DELTA;return 0} if !option.is_null(){ let len=option.offset_from(str_) as usize; option=option.add(1); if len>=buf.len(){return -EINVAL} strncpy(buf.as_mut_ptr(),str_,len); buf[len]=0; cstr=buf.as_ptr(); } for i in 0..COMPUTE_MAX{ if strcmp(cstr,compute_names[i])==0{ *cp=i as c_int; return setup_compute_opt(option); }} pr_err(b"Failed: '%s' is not computation method (use 'delta','ratio' or 'wdiff')\n\0".as_ptr() as _,str_); -EINVAL }
unsafe fn period_percent(he:*mut hist_entry, period:u64)->c_double{ (period as c_double*100.0)/(hists__total_period((*he).hists) as c_double) }
unsafe fn compute_delta(he:*mut hist_entry,pair:*mut hist_entry)->c_double{ let old=period_percent(he,(*he).stat.period); let new=period_percent(pair,(*pair).stat.period); (*pair).diff.period_ratio_delta=new-old; (*pair).diff.computed=true; (*pair).diff.period_ratio_delta }
unsafe fn compute_ratio(he:*mut hist_entry,pair:*mut hist_entry)->c_double{ let old=if (*he).stat.period!=0{(*he).stat.period}else{1} as c_double; let new=(*pair).stat.period as c_double; (*pair).diff.computed=true; (*pair).diff.period_ratio=new/old; (*pair).diff.period_ratio }
unsafe fn compute_wdiff(he:*mut hist_entry,pair:*mut hist_entry)->s64{ (*pair).diff.computed=true; (*pair).diff.wdiff=((*pair).stat.period as s64).wrapping_mul(compute_wdiff_w2).wrapping_sub(((*he).stat.period as s64).wrapping_mul(compute_wdiff_w1)); (*pair).diff.wdiff }
unsafe fn formula_delta(he:*mut hist_entry,pair:*mut hist_entry,buf:*mut c_char,size:size_t)->c_int{ let mut ht=(*(*he).hists).stats.total_period; let mut pt=(*(*pair).hists).stats.total_period; if symbol_conf.filter_relative{ ht=(*(*he).hists).stats.total_non_filtered_period; pt=(*(*pair).hists).stats.total_non_filtered_period;} scnprintf(buf,size,b"(%lu * 100 / %lu) - (%lu * 100 / %lu)\0".as_ptr() as _,(*pair).stat.period,pt,(*he).stat.period,ht)}
unsafe fn formula_ratio(he:*mut hist_entry,pair:*mut hist_entry,buf:*mut c_char,size:size_t)->c_int{ scnprintf(buf,size,b"%.0F / %.0F\0".as_ptr() as _,(*pair).stat.period as c_double,(*he).stat.period as c_double)}
unsafe fn formula_wdiff(he:*mut hist_entry,pair:*mut hist_entry,buf:*mut c_char,size:size_t)->c_int{ scnprintf(buf,size,b"(%lu * %ld) - (%lu * %ld)\0".as_ptr() as _,(*pair).stat.period,compute_wdiff_w2,(*he).stat.period,compute_wdiff_w1)}
unsafe fn formula_fprintf(he:*mut hist_entry,pair:*mut hist_entry,buf:*mut c_char,size:size_t)->c_int{ match compute{COMPUTE_DELTA|COMPUTE_DELTA_ABS=>formula_delta(he,pair,buf,size),COMPUTE_RATIO=>formula_ratio(he,pair,buf,size),COMPUTE_WEIGHTED_DIFF=>formula_wdiff(he,pair,buf,size),_=>{BUG_ON(1);-1}}}

unsafe extern "C" fn block_hist_zalloc(size:size_t)->*mut c_void{ let bh=zalloc(size+mem::size_of::<block_hist>()) as *mut block_hist; if bh.is_null(){ptr::null_mut()}else{&mut (*bh).he as *mut _ as *mut c_void}}
unsafe extern "C" fn block_hist_free(he:*mut c_void){ let bh=bh_from_he(he as *mut hist_entry); hists__delete_entries(&mut (*bh).block_hists); free(bh as *mut c_void)}
